#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_INPUT 1024          /* limit used by the original binary */
#define OUT_BUF   (MAX_INPUT+1) /* space for the terminating NUL */

int main(int argc, char *argv[])
{
    /* No argument – the program prints “EMPTY”. */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *in = argv[1];
    size_t len = strlen(in);
    if (len > MAX_INPUT)               /* the binary truncates long inputs */
        len = MAX_INPUT;

    char out[OUT_BUF];
    size_t out_idx = 0;

    bool have_word   = false;   /* have we already written a non‑whitespace character? */
    bool need_space  = false;   /* did we just pass a run of whitespace after a word? */

    for (size_t i = 0; i < len; ++i) {
        char c = in[i];

        /* whitespace characters recognised by the original program */
        if (c == ' '  || c == '\t' || c == '\n' ||
            c == '\r' || c == '\v' || c == '\f') {

            if (have_word)               /* internal whitespace – remember to insert a single space */
                need_space = true;
            /* leading whitespace is simply ignored */
        } else {
            if (need_space && out_idx > 0) {
                out[out_idx++] = ' ';    /* collapse any run of whitespace to one space */
                need_space = false;
            }
            out[out_idx++] = c;          /* copy the non‑whitespace character */
            have_word = true;            /* we have now output something */
        }
    }

    if (out_idx == 0) {                 /* nothing left after trimming */
        puts("EMPTY");
    } else {
        out[out_idx] = '\0';
        puts(out);
    }
    return 0;
}
